// Realistic agent shell commands for the validation guard (0.6.0 review of the Claude/Codex opt-in).
// expect: 'pass' (not a validation; pipes are fine), 'allowed' (a validation whose exit status stays
// visible), 'block' (a validation whose status a pipe, ;, ||, a following echo or && hides).
// Run in a project whose package.json has "test": "node test.js" and "build": "tsc -p .".
export const BATTERY=[
  // Everyday inspection with pipes (Orca workers, Claude, Codex).
  ['git status -sb | head','pass'],
  ['git log --oneline -20 | head -5','pass'],
  ['git diff --stat | tail -5','pass'],
  ['git status --porcelain | wc -l','pass'],
  ['ls -la | grep test','pass'],
  ['rg -n "npm test" docs | head -20','pass'],
  ['grep -rn "describe(" tests | wc -l','pass'],
  ['cat package.json | jq .scripts','pass'],
  ['npm ls --depth=0 2>/dev/null | head','pass'],
  ['npm view rulesync version | cat','pass'],
  ['gh pr checks 8 | head -20','pass'],
  ['orca orchestration check --json | jq .messages','pass'],
  ['ps aux | grep node | head','pass'],
  ['find . -name "*.test.mjs" | xargs wc -l | tail -1','pass'],
  ['cd /tmp/repo && git status | head','pass'],
  ['git add -A && git commit -m "fix tests" && git push','pass'],
  ['npm install && git status','pass'],
  ['echo "run npm test later" | cat','pass'],
  ['node --version && npm --version','pass'],
  ['docker compose ps | head','pass'],
  ['sed -n 1,40p tests/a.test.mjs | cat','pass'],
  ['tail -50 /tmp/test.log | grep -i error','pass'],
  // Direct validations and the status-keeping forms.
  ['npm test','allowed'],
  ['npm run test:unit -- --reporter=dot','allowed'],
  ['CI=1 npm test','allowed'],
  ['cd web && npm test','allowed'],
  ['(cd web && npm test)','allowed'],
  ['set -o pipefail; npm test 2>&1 | tail -20','allowed'],
  // PIPESTATUS is bash-only: zsh (Claude Code and Codex on macOS) exits 0 here.
  ['npm test 2>&1 | tail -20; exit ${PIPESTATUS[0]}','block'],
  ['npm test > /tmp/aw.log 2>&1; echo "exit=$?"','allowed'],
  ['cd web && npm test > log 2>&1; echo "exit=$?"','allowed'],
  ['pytest -q','allowed'],
  ['go test ./...','allowed'],
  ['npm run check','allowed'],
  // Status-hiding validations.
  ['npm test 2>&1 | tail -20','block'],
  ['npm test; echo "exit=$?"','block'],
  ['npm test | head -50','block'],
  ['npm run build && npm test','block'],
  ['cd web && npm test 2>&1 | tail -5','block'],
  ['npm test || true','block'],
  ['pytest -q | tail -3','block'],
  ['go test ./... 2>&1 | grep -v ok','block'],
  ['cargo build 2>&1 | tail','block'],
  ['node --test | tail','block'],
  ['npx vitest run | tail -30','block'],
  ['npm test && echo OK','block'],
  ['bash -c "npm test | tail"','block'],
  ['npm test &','block'],
  ['node test.js | tail','block'],
  ['npm ci && npm test','block'],
];
